%macro winsor(db_in=temp, db_out=temp,
vars=tacc ch_sale ch_sale_ar ppe inv_ta,
byvar=year,type=winsor, pctl=1 99);
%if &db_out = %then %let db_out = &db_in;%let varL=;%let varH=;%let xn=1;
%do %until ( %scan(&vars,&xn)= );%let token = %scan(&vars,&xn);%let varL = &varL &token.L;%let varH = &varH &token.H;%let xn=%EVAL(&xn + 1);%end;
%let xn=%eval(&xn-1);data xtemp;set &db_in;run;
%if &byvar = none %then %do;data xtemp;set xtemp;xbyvar = 1;run;%let byvar = xbyvar;%end;
