do xi = 1 to dim(trimvars);%if &type = winsor %then %do;if not missing(trimvars{xi}) then do;
if (trimvars{xi} < trimvarl{xi}) then trimvars{xi} = trimvarl{xi};if (trimvars{xi} > trimvarh{xi}) then trimvars{xi} = trimvarh{xi};end;%end;
%else %do;if not missing(trimvars{xi}) then do;if (trimvars{xi} < trimvarl{xi}) then delete;if (trimvars{xi} > trimvarh{xi}) then delete;end;%end;end;
drop &varL &varH xi;run;
